type ChannelActionBehavior = {
  /** Toggle state of the action; omitted for one-shot actions such as leave. */
  'aria-pressed'?: boolean;
  title: string;
  toggle: () => Promise<void>;
};

// The core actions call the API and report the result. The placement wrappers below own the busy
// and menu-close behavior.
const useMuteAction = (): ChannelActionBehavior => {
  const { addNotification } = useNotificationApi();
  const { channel } = useChannelListItemContext();
  const { t } = useTranslationContext();
  const { muted: isMuted } = useIsChannelMuted(channel);

  const toggle = async () => {
    try {
      if (isMuted) {
        await channel.unmute();
        addNotification({
          context: { channel },
          emitter: ChannelListItemActionButtons.name,
          message: t('common.channelUnmuted.text', 'Channel unmuted'),
          severity: 'success',
          type: 'api:channel:unmute:success',
        });
      } else {
        await channel.mute();
        addNotification({
          context: { channel },
          emitter: ChannelListItemActionButtons.name,
          message: t('common.channelMuted.text', 'Channel muted'),
          severity: 'success',
          type: 'api:channel:mute:success',
        });
      }
    } catch (error) {
      addNotification({
        context: { channel },
        emitter: ChannelListItemActionButtons.name,
        error: error instanceof Error ? error : new Error('An unknown error occurred'),
        message: t(
          'channelListItem.failedUpdateChannelMute.text',
          'Failed to update channel mute status',
        ),
        severity: 'error',
        type: 'api:channel:mute:failed',
      });
    }
  };

  return {
    'aria-pressed': isMuted,
    title: isMuted ? t('common.unmute.title', 'Unmute') : t('common.mute.title', 'Mute'),
    toggle,
  };
};

