// Quick (hover/focus-revealed) action button. Busy state uses `aria-disabled` and `aria-busy`, not
// `disabled`, which would blur the button and collapse its hover-revealed row.
const useQuickActionButtonProps = ({
  'aria-pressed': ariaPressed,
  title,
  toggle,
}: ChannelActionBehavior) => {
  // A ref latch flips synchronously, so two clicks in the same tick cannot both call `toggle()`;
  // the `aria-*` state only guards after the rerender, too late for non-idempotent actions.
  const inProgressRef = useRef(false);
  const [inProgress, setInProgress] = useState(false);

  return {
    'aria-busy': inProgress || undefined,
    'aria-disabled': inProgress || undefined,
    'aria-pressed': ariaPressed,
    onClick: async (e: React.MouseEvent<HTMLButtonElement>) => {
      e.stopPropagation();
      if (inProgressRef.current) return;
      inProgressRef.current = true;
      try {
        setInProgress(true);
        await toggle();
      } finally {
        inProgressRef.current = false;
        setInProgress(false);
      }
    },
    title,
  } satisfies ComponentPropsWithoutRef<'button'>;
};

// Dropdown menu item: activating closes the menu, which returns focus to the toggle, and runs the
// action in the background, so the item needs no busy state.
//
// The action runs on the next animation frame, after the close commits. The open menu is an
// aria-modal dialog with its own `AriaLiveOutlet` (the root outlet is inert meanwhile), so a
// notification raised synchronously can land in that outlet as it unmounts and never be spoken.
const useDropdownActionButtonProps = ({
  'aria-pressed': ariaPressed,
  title,
  toggle,
}: ChannelActionBehavior) => {
  const { closeMenu } = useContextMenuContext();

  return {
    'aria-pressed': ariaPressed,
    onClick: (e: React.MouseEvent<HTMLButtonElement>) => {
      e.stopPropagation();
      closeMenu();
      requestAnimationFrame(() => void toggle());
    },
    title,
  } satisfies ComponentPropsWithoutRef<'button'>;
};

// Blocks or unblocks the other member of a DM.
const useBanAction = (): ChannelActionBehavior => {
  const { client } = useChatContext();
  const { addNotification } = useNotificationApi();
  const { t } = useTranslationContext();
  const { channel } = useChannelListItemContext();
  const members = useChannelMembersState(channel);
  const isUserBanned = Object.values(members || {}).some(
    (member) => member.user?.id !== client.userID && member.banned,
  );

  const toggle = async () => {
    try {
      const otherUserId = Object.keys(channel.state.members).find(
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        (userId) => userId !== client.userID!,
      );
      if (!otherUserId) return;
      if (isUserBanned) {
        await channel.unbanUser(otherUserId);
        addNotification({
          context: { channel },
          emitter: ChannelListItemActionButtons.name,
          message: t('common.userUnblocked.text', 'User unblocked'),
          severity: 'success',
          type: 'api:user:unban:success',
        });
      } else {
        await channel.banUser(otherUserId, {});
        addNotification({
          context: { channel },
          emitter: ChannelListItemActionButtons.name,
          message: t('common.userBlocked.text', 'User blocked'),
          severity: 'success',
          type: 'api:user:ban:success',
        });
      }
    } catch (error) {
      addNotification({
        context: { channel },
        emitter: ChannelListItemActionButtons.name,
        error: error instanceof Error ? error : new Error('An unknown error occurred'),
        message: t('channelListItem.failedBlockUser.text', 'Failed to block user'),
        severity: 'error',
        type: 'api:user:ban:failed',
      });
    }
  };

  return {
    'aria-pressed': isUserBanned,
    title: isUserBanned
      ? t('channelListItem.unblockUser.title', 'Unblock User')
      : t('common.blockUser.title', 'Block User'),
    toggle,
  };
};

// One-shot, so it returns no `aria-pressed`.
const useLeaveAction = (): ChannelActionBehavior => {
  const { t } = useTranslationContext();
  const { channel } = useChannelListItemContext();
  const { client } = useChatContext();
  const { addNotification } = useNotificationApi();

  const toggle = async () => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      await channel.removeMembers({ members: [client.userID!] });
      addNotification({
        context: { channel },
        emitter: ChannelListItemActionButtons.name,
        message: t('common.leftChannel.text', 'Left channel'),
        severity: 'success',
        type: 'api:channel:leave:success',
      });
    } catch (error) {
      addNotification({
        context: { channel },
        emitter: ChannelListItemActionButtons.name,
        error: error instanceof Error ? error : new Error('An unknown error occurred'),
        message: t('common.failedLeaveChannel.text', 'Failed to leave channel'),
        severity: 'error',
        type: 'api:channel:leave:failed',
      });
    }
  };

  return { title: t('channelListItem.leaveChannel.title', 'Leave Channel'), toggle };
};

