type ChannelActionItem =
  | (({ placement: 'quick' } | { placement: 'dropdown' }) & {
      type: string;
      Component: React.ComponentType;
    })
  | {
      placement: 'quick-dropdown-toggle';
      Component: React.ComponentType<ComponentPropsWithRef<'button'>>;
    };

const defaultComponents = {
  dropdown: {
    Archive() {
      const { IconArchive } = useComponentContextIcons();
      const behaviorProps = useDropdownActionButtonProps(useArchiveAction());

      return (
        <ContextMenuButton
          aria-label={behaviorProps.title}
          data-testid='dropdown-action-archive'
          Icon={IconArchive}
          {...behaviorProps}
        >
          {behaviorProps.title}
        </ContextMenuButton>
      );
    },
    Ban() {
      const { IconNoSign } = useComponentContextIcons();
      const behaviorProps = useDropdownActionButtonProps(useBanAction());

      return (
        <ContextMenuButton
          aria-label={behaviorProps.title}
          data-testid='dropdown-action-ban'
          Icon={IconNoSign}
          {...behaviorProps}
        >
          {behaviorProps.title}
        </ContextMenuButton>
      );
    },
    Leave() {
      const { IconLeave } = useComponentContextIcons();
      const behaviorProps = useDropdownActionButtonProps(useLeaveAction());

      return (
        <ContextMenuButton
          aria-label={behaviorProps.title}
          data-testid='dropdown-action-leave'
          Icon={IconLeave}
          variant='destructive'
          {...behaviorProps}
        >
          {behaviorProps.title}
        </ContextMenuButton>
      );
    },
    Mute() {
      const { IconMute } = useComponentContextIcons();
      const behaviorProps = useDropdownActionButtonProps(useMuteAction());

      return (
        <ContextMenuButton
          aria-label={behaviorProps.title}
          data-testid='dropdown-action-mute'
          Icon={IconMute}
          {...behaviorProps}
        >
          {behaviorProps.title}
        </ContextMenuButton>
      );
    },
    Pin() {
      const { IconPin } = useComponentContextIcons();
      const behaviorProps = useDropdownActionButtonProps(usePinAction());

      return (
        <ContextMenuButton
          aria-label={behaviorProps.title}
          data-testid='dropdown-action-pin'
          Icon={IconPin}
          {...behaviorProps}
        >
          {behaviorProps.title}
        </ContextMenuButton>
      );
    },
  },
  quick: {
    Archive() {
      const { IconArchive } = useComponentContextIcons();
      const behaviorProps = useQuickActionButtonProps(useArchiveAction());

      return (
        <Button
          appearance='ghost'
          aria-label={behaviorProps.title}
          circular
          data-testid='quick-action-archive'
          size='sm'
          variant='secondary'
          {...behaviorProps}
        >
          <IconArchive />
        </Button>
      );
    },
    Mute() {
      const { IconMute } = useComponentContextIcons();
      const behaviorProps = useQuickActionButtonProps(useMuteAction());

      return (
        <Button
          appearance='ghost'
          aria-label={behaviorProps.title}
          circular
          data-testid='quick-action-mute'
          size='sm'
          variant='secondary'
          {...behaviorProps}
        >
          <IconMute />
        </Button>
      );
    },
  },
  QuickDropdownToggle: forwardRef<HTMLButtonElement>((_, ref) => {
    const { IconMore } = useComponentContextIcons();
    const { channel } = useChannelListItemContext();
    const { t } = useTranslationContext();

    const dialogId = ChannelListItemActionButtons.getDialogId({
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      channelId: channel.id!,
    });
    const { dialog, dialogManager } = useDialogOnNearestManager({ id: dialogId });
    const dialogIsOpen = useDialogIsOpen(dialogId, dialogManager?.id);

    return (
      <Button
        appearance='ghost'
        aria-expanded={dialogIsOpen}
        aria-label={t(
          'channelListItem.openChannelActionsMenu.ariaLabel',
          'Open Channel Actions Menu',
        )}
        aria-pressed={dialogIsOpen}
        circular
        data-testid='channel-list-item-dropdown-toggle'
        onClick={(e) => {
          e.stopPropagation();

          dialog.toggle();
        }}
        ref={ref}
        size='sm'
        variant='secondary'
      >
        <IconMore />
      </Button>
    );
  }),
};

defaultComponents.QuickDropdownToggle.displayName = 'QuickDropdownToggle';

